import "primereact/resources/themes/lara-light-indigo/theme.css";  // Theme
import "primereact/resources/primereact.min.css";  // Core styles
import "primeicons/primeicons.css";  // PrimeIcons
import React, { useState, useEffect, useRef } from "react";
import { DataTable } from "primereact/datatable";
import { Column } from "primereact/column";
import { Button } from "primereact/button";
import { Toast } from "primereact/toast";
import { Dialog } from "primereact/dialog";
import axios from "axios";
import "./css/VetAppointments.css";

const VetAppointments = () => {
    const clinicId = localStorage.getItem("clinicId");
    const [appointments, setAppointments] = useState([]);
    const [selectedAppointment, setSelectedAppointment] = useState(null);
    const [editDialog, setEditDialog] = useState(false);
    const toast = useRef(null);

    useEffect(() => {
        fetchAppointments();
    }, []);

    const fetchAppointments = async () => {
        try {
            const response = await axios.get(`http://localhost:5000/api/appointments/clinics/${clinicId}`);
            const filteredAppointments = response.data.filter(appt => ["pending", "confirmed"].includes(appt.status?.toLowerCase()));
            setAppointments(filteredAppointments);
        } catch (error) {
            toast.current.show({ severity: "error", summary: "Error", detail: "Failed to fetch appointments." });
        }
    };

    const showToast = (severity, summary, detail) => {
        toast.current.show({ severity, summary, detail, life: 3000 });
    };

    const updateAppointmentStatus = async (id, status) => {
        try {
            const updateData = { status, confirmedAt: null, completedAt: null, rejectedAt: null };
            if (status === "Confirmed") updateData.confirmedAt = new Date();
            if (status === "Completed") updateData.completedAt = new Date();
            if (status === "Cancelled") updateData.rejectedAt = new Date();
            
            await axios.put(`http://localhost:5000/api/appointments/update/${id}`, updateData);
            showToast("success", "Updated", `Appointment marked as ${status}.`);
            fetchAppointments();
        } catch (error) {
            showToast("error", "Error", "Failed to update appointment status.");
        }
    };

    const handleEdit = (appointment) => {
        setSelectedAppointment(appointment);
        setEditDialog(true);
    };

    const handleUpdate = async (id, status) => {
        if (!id) return;
        try {
            await axios.put(`http://localhost:5000/api/appointments/update/${id}`, { status });
            showToast("success", "Updated", `Appointment marked as ${status}.`);
            fetchAppointments();
            setEditDialog(false);
        } catch (error) {
            showToast("error", "Error", "Failed to update appointment status.");
        }
    };

    const dateTemplate = (rowData) => new Date(rowData.date).toLocaleString();

    const formatStatus = (rowData) => (
        <span className={`status-tag ${rowData.status.toLowerCase()}`}>{rowData.status.toUpperCase()}</span>
    );

    const actionTemplate = (rowData) => (
        <div className="flex gap-2">
            <Button icon="pi pi-pencil" className="p-button-sm p-button-outlined" onClick={() => handleEdit(rowData)} />
            {rowData.status === "Pending" && (
                <>
                    <Button icon="pi pi-check" className="p-button-success p-button-sm" onClick={() => updateAppointmentStatus(rowData._id, "Confirmed")} />
                    <Button icon="pi pi-times" className="p-button-danger p-button-sm" onClick={() => updateAppointmentStatus(rowData._id, "Cancelled")} />
                </>
            )}
            {rowData.status === "Confirmed" && (
                <Button icon="pi pi-check" className="p-button-success p-button-sm" onClick={() => updateAppointmentStatus(rowData._id, "Completed")} />
            )}
        </div>
    );

    return (
        <div className="p-card p-4">
            <Toast ref={toast} position="bottom-right" />
            <h2 className="p-text-bold text-xl mb-4">Pending Appointments</h2>
            <DataTable value={appointments} className="p-datatable-striped" paginator rows={5} responsiveLayout="scroll">
                <Column field="ownerName" header="Owner Name" sortable />
                <Column field="petDetails" header="Pet Details" sortable />
                <Column field="service_id.name" header="Service Availed" sortable />
                <Column field="date" header="Appointment Date" body={dateTemplate} sortable />
                <Column field="status" header="Status" body={formatStatus} sortable />
                <Column header="Actions" body={actionTemplate} />
            </DataTable>

            <Dialog visible={editDialog} header="Edit Appointment" onHide={() => setEditDialog(false)} className="p-fluid" style={{ width: '400px' }}>
                {selectedAppointment && (
                    <div className="p-field">
                        <label>Status</label>
                        <select className="p-inputtext" value={selectedAppointment?.status || ""} onChange={(e) => setSelectedAppointment({ ...selectedAppointment, status: e.target.value })}>
                            {selectedAppointment.status === "Pending" && (
                                <>
                                    <option value="Confirmed">Confirmed</option>
                                    <option value="Cancelled">Cancelled</option>
                                </>
                            )}
                            {selectedAppointment.status === "Confirmed" && <option value="Completed">Completed</option>}
                        </select>
                    </div>
                )}
                <div className="p-dialog-footer">
                    <Button label="Cancel" className="p-button-text" onClick={() => setEditDialog(false)} />
                    <Button label="Update" className="p-button-primary" onClick={() => handleUpdate(selectedAppointment._id, selectedAppointment.status)} />
                </div>
            </Dialog>
        </div>
    );
};

export default VetAppointments;
